<?php
require_once dirname(__DIR__) . '/app/config.php'; require_admin(); csrf_check();
$validTabs=['dashboard','books','orders','users','posts'];
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $a=$_POST['action']??''; $tab=$_POST['tab']??'books';
    try {
        if ($a==='book_save') {
            $id=(int)($_POST['id']??0); $title=trim($_POST['title']??''); $code=trim($_POST['code']??''); $author=trim($_POST['author']??'');
            if ($title==='' || $code==='' || $author==='') throw new RuntimeException('Vui lòng nhập tên, mã giáo trình và tác giả.');
            $old=null; if($id){$s=$pdo->prepare('SELECT * FROM books WHERE id=?');$s->execute([$id]);$old=$s->fetch();if(!$old)throw new RuntimeException('Không tìm thấy giáo trình.');}
            $cover=upload_book_file('cover','cover',$old['cover_image']??null);
            $pdf=upload_book_file('pdf','pdf',$old['file_path']??null);
            $data=[$title,$code,$author,(int)($_POST['category_id']??0) ?: null,max(0,(float)($_POST['price']??0)),trim($_POST['description']??''),$cover,trim($_POST['publisher']??''),($_POST['publish_year']??'')!==''?(int)$_POST['publish_year']:null,($_POST['pages']??'')!==''?(int)$_POST['pages']:null,trim($_POST['language']??''),trim($_POST['isbn']??''),$pdf];
            if($id){$s=$pdo->prepare('UPDATE books SET title=?,code=?,author=?,category_id=?,price=?,description=?,cover_image=?,publisher=?,publish_year=?,pages=?,language=?,isbn=?,file_path=? WHERE id=?');$s->execute([...$data,$id]);}
            else{$s=$pdo->prepare("INSERT INTO books(title,code,author,category_id,price,description,cover_image,publisher,publish_year,pages,language,isbn,file_path,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'active')");$s->execute($data);}
            flash('success','Đã lưu đầy đủ thông tin giáo trình.');
        } elseif($a==='category_save') {
            $name=trim($_POST['name']??''); if($name==='')throw new RuntimeException('Nhập tên danh mục.');
            $s=$pdo->prepare('INSERT INTO categories(name,description) VALUES(?,?)');$s->execute([$name,trim($_POST['description']??'')]);flash('success','Đã thêm danh mục.');
        } elseif($a==='book_delete') {$pdo->prepare("UPDATE books SET status='deleted' WHERE id=?")->execute([(int)$_POST['id']]);flash('success','Đã ẩn giáo trình.');
        } elseif($a==='book_restore') {$pdo->prepare("UPDATE books SET status='active' WHERE id=?")->execute([(int)$_POST['id']]);flash('success','Đã khôi phục giáo trình.');
        } elseif($a==='order_status') { $allowed=['pending','processing','shipping','completed','cancelled'];$s=$_POST['status']??'';if(!in_array($s,$allowed,true))throw new RuntimeException('Trạng thái đơn hàng không hợp lệ.');$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$s,(int)$_POST['id']]);flash('success','Đã cập nhật đơn hàng.');
        } elseif($a==='user_status') {$s=$_POST['status']??'';if(!in_array($s,['active','blocked'],true))throw new RuntimeException('Trạng thái tài khoản không hợp lệ.');$pdo->prepare("UPDATE users SET status=? WHERE id=? AND role<>'admin'")->execute([$s,(int)$_POST['id']]);flash('success','Đã cập nhật tài khoản.');
        } elseif($a==='post_status') {$s=$_POST['status']??'';if(!in_array($s,['published','hidden'],true))throw new RuntimeException('Trạng thái bài viết không hợp lệ.');$pdo->prepare('UPDATE posts SET status=? WHERE id=?')->execute([$s,(int)$_POST['id']]);flash('success','Đã cập nhật bài đăng.');}
    } catch(Throwable $ex) { flash('danger',$ex instanceof PDOException ? 'Không thể lưu dữ liệu. Kiểm tra mã giáo trình có bị trùng không và đã chạy upgrade_database.sql chưa.' : $ex->getMessage()); }
    redirect('admin.php?tab='.urlencode(in_array($tab,$validTabs,true)?$tab:'books'));
}
$tab=$_GET['tab']??'dashboard';if(!in_array($tab,$validTabs,true))$tab='dashboard';
$stats=['books'=>$pdo->query("SELECT COUNT(*) FROM books WHERE status='active'")->fetchColumn(),'users'=>$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(),'orders'=>$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'revenue'=>$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status='completed'")->fetchColumn()];
$books=$pdo->query("SELECT b.*,c.name category FROM books b LEFT JOIN categories c ON c.id=b.category_id WHERE b.status<>'deleted' ORDER BY b.id DESC")->fetchAll();
$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();
$orders=$pdo->query('SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC')->fetchAll();
$users=$pdo->query('SELECT * FROM users ORDER BY id DESC')->fetchAll();
$posts=$pdo->query('SELECT p.*,u.name FROM posts p JOIN users u ON u.id=p.user_id ORDER BY p.id DESC')->fetchAll();
header_html('Quản trị IT-Books'); ?>
<div class="admin-heading d-flex justify-content-between align-items-center flex-wrap mb-4"><div><span class="eyebrow">IT-BOOKS CONTROL CENTER</span><h1 class="fw-bold mb-1">Quản trị hệ thống</h1><p class="text-muted mb-0">Quản lý thư viện, thành viên và hoạt động bán giáo trình.</p></div><span class="badge bg-dark p-2">ADMINISTRATOR</span></div>
<ul class="nav nav-pills gap-2 mb-4 admin-tabs"><?php foreach(['dashboard'=>'Tổng quan','books'=>'Giáo trình','orders'=>'Đơn hàng','users'=>'Tài khoản','posts'=>'Cộng đồng'] as $k=>$v):?><li class="nav-item"><a class="nav-link <?=$tab===$k?'active':''?>" href="?tab=<?=$k?>"><?=$v?></a></li><?php endforeach;?></ul>
<?php if($tab==='dashboard'):?><div class="row g-3 mb-4"><?php foreach(['books'=>'Giáo trình đang bán','users'=>'Thành viên','orders'=>'Đơn hàng'] as $k=>$v):?><div class="col-sm-6 col-xl-3"><div class="stat-card"><span><?=$v?></span><strong><?=number_format((int)$stats[$k])?></strong></div></div><?php endforeach;?><div class="col-sm-6 col-xl-3"><div class="stat-card"><span>Doanh thu hoàn thành</span><strong><?=money($stats['revenue'])?></strong></div></div></div><div class="card border-0 shadow-sm p-4 mb-3" data-admin-events><div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><div><h5 class="fw-bold mb-1"><i class="fa-solid fa-tower-broadcast text-primary me-2"></i>Đơn hàng đang chờ</h5><p class="text-muted mb-0">Số liệu được cập nhật trực tiếp bằng Server-Sent Events.</p></div><div class="display-6 fw-bold text-primary" data-pending-count>—</div></div></div><div class="card border-0 shadow-sm p-4"><h5>Quản lý nhanh</h5><p class="text-muted mb-3">Cập nhật ảnh bìa, thông tin xuất bản và tài liệu PDF trong mục Giáo trình.</p><a class="btn btn-primary align-self-start" href="?tab=books">Quản lý giáo trình</a></div>
<?php elseif($tab==='books'):?>
<div class="card border-0 shadow-sm p-3 mb-3"><h5 class="fw-bold">Thêm danh mục</h5><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="category_save"><input type="hidden" name="tab" value="books"><div class="col-md-4"><input class="form-control" name="name" placeholder="Tên danh mục mới" required></div><div class="col-md-6"><input class="form-control" name="description" placeholder="Mô tả danh mục"></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Thêm danh mục</button></div></form></div>
<div class="card border-0 shadow-sm p-3 p-lg-4 mb-4"><div class="d-flex justify-content-between flex-wrap align-items-center mb-3"><div><h4 class="fw-bold mb-1">Thêm giáo trình mới</h4><p class="text-muted mb-0">Có thể thêm ảnh bìa và file PDF để người đọc xem thông tin chi tiết.</p></div></div>
<form method="post" enctype="multipart/form-data" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="book_save"><input type="hidden" name="tab" value="books">
<div class="col-md-6"><label class="form-label">Tên giáo trình *</label><input class="form-control" name="title" required></div><div class="col-md-3"><label class="form-label">Mã học phần *</label><input class="form-control" name="code" required></div><div class="col-md-3"><label class="form-label">Tác giả *</label><input class="form-control" name="author" required></div>
