<div class="col-md-3"><label class="form-label">Giá (VNĐ)</label><input class="form-control" type="number" name="price" min="0" value="0"></div><div class="col-md-3"><label class="form-label">Ngôn ngữ</label><input class="form-control" name="language" placeholder="Tiếng Việt"></div><div class="col-md-3"><label class="form-label">ISBN</label><input class="form-control" name="isbn"></div><div class="col-md-3"><label class="form-label">Ảnh bìa (JPG/PNG/WEBP)</label><input class="form-control" type="file" name="cover" accept="image/jpeg,image/png,image/webp"></div>
<div class="col-md-6"><label class="form-label">Tài liệu PDF (tối đa 25MB)</label><input class="form-control" type="file" name="pdf" accept="application/pdf"></div><div class="col-12"><label class="form-label">Mô tả / nội dung giáo trình</label><textarea class="form-control" name="description" rows="3" placeholder="Giới thiệu nội dung, kiến thức và đối tượng phù hợp..."></textarea></div><div class="col-12"><button class="btn btn-primary px-4"><i class="fa fa-plus me-2"></i>Thêm giáo trình</button></div></form></div>
<div class="card border-0 shadow-sm table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Ảnh</th><th>Giáo trình</th><th>Mã / Danh mục</th><th>Giá</th><th>Thao tác</th></tr></thead><tbody><?php foreach($books as $b):?><tr><td><img class="admin-thumb" src="<?=e(book_cover($b['cover_image']))?>" alt=""></td><td><strong><?=e($b['title'])?></strong><br><small class="text-muted"><?=e($b['author'])?></small></td><td><?=e($b['code'])?><br><small class="text-muted"><?=e($b['category']??'Chưa phân loại')?></small></td><td><?=money($b['price'])?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="book_edit.php?id=<?=$b['id']?>">Sửa</a> <form method="post" class="d-inline" onsubmit="return confirm('Ẩn giáo trình này?')"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="book_delete"><input type="hidden" name="tab" value="books"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="btn btn-sm btn-outline-danger">Ẩn</button></form></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($tab==='orders'):?><div class="card border-0 shadow-sm table-responsive"><table class="table align-middle"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Địa chỉ</th><th>Tổng tiền</th><th>Trạng thái</th><th>Cập nhật</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['customer_name'])?><br><small><?=e($o['email'])?> · <?=e($o['phone'])?></small></td><td><?=e($o['address'])?></td><td><?=money($o['total'])?></td><td><?=e($o['status'])?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="order_status"><input type="hidden" name="tab" value="orders"><input type="hidden" name="id" value="<?=$o['id']?>"><select class="form-select form-select-sm" name="status"><?php foreach(['pending','processing','shipping','completed','cancelled'] as $s):?><option <?=$o['status']===$s?'selected':''?> value="<?=$s?>"><?=$s?></option><?php endforeach;?></select><button class="btn btn-sm btn-primary">Lưu</button></form></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($tab==='users'):?><div class="card border-0 shadow-sm table-responsive"><table class="table align-middle"><thead><tr><th>Họ tên</th><th>Email</th><th>Vai trò</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=e($u['status'])?></td><td><?php if($u['role']!=='admin'):?><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="user_status"><input type="hidden" name="tab" value="users"><input type="hidden" name="id" value="<?=$u['id']?>"><select name="status" class="form-select form-select-sm"><option value="active" <?=$u['status']==='active'?'selected':''?>>Hoạt động</option><option value="blocked" <?=$u['status']==='blocked'?'selected':''?>>Khóa</option></select><button class="btn btn-sm btn-primary">Lưu</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($tab==='posts'):?><div class="card border-0 shadow-sm table-responsive"><table class="table align-middle"><thead><tr><th>Người đăng</th><th>Nội dung</th><th>Trạng thái</th><th>Cập nhật</th></tr></thead><tbody><?php foreach($posts as $p):?><tr><td><?=e($p['name'])?></td><td><?=e(mb_strimwidth($p['content'],0,120,'…'))?></td><td><?=e($p['status'])?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="post_status"><input type="hidden" name="tab" value="posts"><input type="hidden" name="id" value="<?=$p['id']?>"><select name="status" class="form-select form-select-sm"><option value="published">Hiển thị</option><option value="hidden">Ẩn</option></select><button class="btn btn-sm btn-primary">Lưu</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
